  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (506::BIGINT, 'No se le entiende nada, los quices no son difíciles pero si lleva con el sepa que va a tener que estudiar de forma independiente porque si se queda solo con lo que el dice en los exámenes se lo van a sonar,'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '495ce8fc2088a9651f54188dbd08c94d47fd733ace254a8c54a3c86ed4853727'::TEXT, ARRAY[634]::BIGINT[]),
    (506::BIGINT, 'llevé algebra con él y la materia la explicó bien. el one note es una mierda, los apuntes son desordenados, se tiene que estudiar por cuenta propia bastante, adelantar la materia antes ayuda mucho. Los quices no son complicados si se estudia con tiempo, además avisaba siempre. califica fuerte y bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd77896f2b43a713b345f7e01085936d9e2d2af0cfc4fbc65d382a210dd0d23ad'::TEXT, ARRAY[634]::BIGINT[]),
    (506::BIGINT, 'El curso como tal es pesado, pero pensé que el profesor iba a ser peor para como lo pintan las reseñas. El profe tiene una personalidad que no es del agrado de todos, pero si usted se concentra en el curso puede pasarlo el profesor no es una traba.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-10T00:00:00+00:00'::TIMESTAMPTZ, '750625fd9916807751e944943834a9e9021195258f15b96ca80ebf428ab73341'::TEXT, ARRAY[634]::BIGINT[]),
    (506::BIGINT, 'Es flexible con las calificaciones serias (Quices, examenes) pero un dolor con calificaciones ridicular. Pide que le entreguemos afiches "bien hechos", pero ninguno le gusta, "no aceptaré trabajos mediocres" dice. Cuando le pregunta como se ve un buen afiche, él le muestra una pagina web...'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '5ebec76bcfb9943844240c534f9a151c57a28b165f0d5bc92effd9ebea1ce68a'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'SI TIENE LA OPORTUNIDAD DE MATRICULAR CON ÉL DESAPROVECHELA PORFAVOR'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-30T00:00:00+00:00'::TIMESTAMPTZ, '07605a9d02da3bfa7b3b77499b8290bfaafa79dd18ad91e22142756381729358'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Mae vea, el mae no explica nada literalmente. Manda khan academys y de eso agarre para su saco. Las clases son aburridisimas, solo 4 de 10 estudiantes pasan el curso. Usa pesimas metaforas, como si estuviera fumado. El one note es una mierda.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-04-16T00:00:00+00:00'::TIMESTAMPTZ, 'e5571917d69df8aa17e7081d6fba687f3193f9f79146c522bbbb6c7364318b29'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Tiene un carácter un poco fuerte, opina con todo el respeto así que es importante no tomarse las cosas personales y ver el lado positivo de lo que dice, es importante también repasar ciertas bases porque tiene una alta crítica hacia los sistemas educativos y sus deficiencias en Matemática.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, '18ead86ff8a337e00531e40ebe099b5fe4d0282da333228344c48153167e5377'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'La gestión pedagógica del profesor resulta, por desgracia, profundamente desconcertante. Su proceder denota una proclividad a actitudes anacrónicas y poco edificantes, especialmente en lo que respecta al trato hacia sus estudiantes mujeres. Tal comportamiento, impregnado de un matiz claramente impro'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'b01c02f24986093c40171de0b7b3d5634b27c5ecc60fd22a1c138389c863d053'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'No lo recomiendo si está llevando mate por primera vez y tiene malas bases, es muy grosero y desordenado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '042b6053d16eedc0613b3c42690d6128214056590849e0396fb0fd71d966fcab'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Horrible profesor, tanto en la materia como en lo personal, es odioso y burlista, aparte de que no sabe explicar en lo más mínimo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '63a76079c19704e36912ac44864226acfa75c31c36a472e9ddfb75bcda8e1538'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Si tiene la oportunidad de evitarlo, HÁGALO, el PEOR profesor que he tenido por mucho, grosero, machista, burlista, no sabe dar la clase, el One Note es LO PEOR, el material todo desordenado, aparte de que habla demasiada papaya, demasiado humillante y no vale la pena como persona ni como profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'e23de28440e1d45c0fe92babf8a54ee321fddc2d101dfecd2270e970288064f8'::TEXT, ARRAY[1684]::BIGINT[]),
    (506::BIGINT, 'Evite a toda costa, el one note ese solo lo entiende el, mucho estudio por parte de uno mismo. No deja claras las cosas y utiliza la minima situacion para burlarse de la gente'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'e879590aeb1f9b1e67383b50c76234372e8d54eb7cf3a8e520736189e9b80921'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'No es un profesor para todos, él es muy grosero (no es una mala gente), si usted le pregunta algo le va a responder bien, pero se burla bastante de los errores que han cometido los estudiantes en semestres pasados, si usted presta atención le ira bien, pero el ambiente es pesado, nadie habla.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2025-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'bfcaafbdb293437f50743ff0ea216643d125958ed595bdd5b5a928ff73ad4769'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Nunca lo lleven, se van a arrepentir demasiado. De los peores Profesores. Explica muy mal, ve la materia viste y luego le va mal a uno en el examen. Pésimo.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'e9e80cfbdedefab4f2dfa4241a8699aa684774607bdfaef007535087cc636f7c'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'No lo recomiendo. Explica mal y muy rápido, tiene una mala actitud hacia quienes pregunten conceptos que él considera "básicos". Definitivamente hay mejores opciones.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f6bdb9c89bbe1616bc096caa2ad8657e0e0de89c3de7dcf20e29d712de619677'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'El profesor juega de sabelotodo, te asusta si eres primer ingreso para que te sientas mal. Además, no se le entiende un carajo cuando habla y explica sin ganas. Honestamente, la única razón para matricular con él, es que ordena todas las clases por semana, y eso sirve mucho para estudiar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'fd8c22d0724d5d7a5de6e282118c2431c9d0b31b01191d7bf7ab7681d4b4b4eb'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'No matricular con él, las clases son largas y es facil de perderse, y cree que uno sabe todo lo que él considera "básico".'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-19T00:00:00+00:00'::TIMESTAMPTZ, 'fe13f2960ff780891b10b47c1226a81ac7cea1d4b66d56fc4c116ab1f141453e'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (506::BIGINT, 'Hágase un favor y NO matricule con él. No sabe explicar y es sumamente prepotente. Se siente muy superior.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '81129d7ecd05269e4d11e76627dddf59399d373d1ba5fc0824f0374e6c52251b'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Si va a tomar su clase sepa que usted va a ir a aprender por su propia cuenta ya que el profesor explica demasiado mal, es muy desordenado. El ayuda con las consultas pero lo deja a uno el doble de confundido, es muy cerrado y no va a buscar más formas de explicar un ejercicio si no lo entendió.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c526c718b91a8633dbd3632a48a8101f25ad9b68c7c53535ba6c62ee13deaac4'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'El profe explica bien, utiliza el one note para dar la clase entonces quedan los apunte, si se pierde en la clase o no va no va a entender nada del one note porque es super desordenado solo el lo entiende'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '372aa635b0936e5fcce57824beb3f38fe9c033f229f458c9ad23835274bc9f0d'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'La verdad si es un buen profe, es muy organizado y se maneja completamente digital. Siempre es muy amable y crea un ambiente en donde a nadie le da miedo preguntar la mínima cosa entonces eso ayuda mucha. Tiene mucha paciencia y si tiene que explicar lo mismo 10 veces, lo hace'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-16T00:00:00+00:00'::TIMESTAMPTZ, '21b69803082df7340a65cf8222d64aefb17bd183ff0d4d9e1a2ad329979199de'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'La verdad que si es buen profe. Las clases son un poco largas pero ayuda cuando se ocupa y atiende dudas. Sin embargo a veces podría explicar con más claridad.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7784e78d3c00af7af98a72cfc1bc5d255dbcc0734aac6041066f71ff2f9d0e34'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'No dejarse llevar por lo otros comentarios, es un buen profesor de cátedra y da mucho apoyo cuando vas mal'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-24T00:00:00+00:00'::TIMESTAMPTZ, '7bc4c86cd19379ba446eb1aa50a2fe6dde605c7357c84cbce4182857739f5676'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-31T00:00:00+00:00'::TIMESTAMPTZ, 'b9abbfafc894efcbf7498b0d66d14435bbbc4c209c0ad04b81e5e5bc0a2ac5e7'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Va a clases a ver cómo resuelve ejercicios q ni él tiene claro, pone mucha presión en el estudiante. EVITE'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2022-12-11T00:00:00+00:00'::TIMESTAMPTZ, '600f697f1e0665343f42fb021a14e7c26c7479b71c93cedf51e199795d137edc'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Mal profe'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, '80c3e8d72be93dd0b5c4a1ee76a06fa04606a4c33f7bd6a90a023e021221aeb1'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'No me gustó para nada la manera en que imparte lecciones dado que no explica bien, hace enrredos al tratar de demostrar los ejercicios y las clases se vuelven cansadas y largas. Evitarlo a toda costa.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c6418f5315f7260ba00158833aae4b53eb7e48bc77eb85ca9e998c8a230b7436'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'No volvería a matricular con él, cree que uno sabe todo y cuando explicar es demasiado confuso, no lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '1e3b9d7fe6100e2f01d4a40bd783bb6022381e2d7ce652b51d8bc424d52a0e4c'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'El profe es pésimo pésimo, se pasa trabando y parece que llega a aprender a las clases; deja trabajos inútiles.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-10-31T00:00:00+00:00'::TIMESTAMPTZ, '617540d74547e1e61a895026f8a1884c635a8c0f50445ab29ed6cfef5bf8bfd5'::TEXT, ARRAY[923]::BIGINT[]),
    (506::BIGINT, 'se trabaja mucho en grupo. si usted lee la materia las clases son para aclarar dudas, trae muchos ejemplos de diferentes materiales que es bueno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-09-22T00:00:00+00:00'::TIMESTAMPTZ, 'cbac6064275ae717124496f0a1835796e2c20def04dc3acfb47b2d0c6f97ca64'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'No lo recomiendo en lo más minimo, es muy confuso a la hora de explicar, se enreda solo y da ejemplos poco claros, ha más no haber matricule con el.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '7c85108db55a145043eceeda048b3fdc388df4cc7e9f54661ab96517ecc209b8'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Explica decente aunque a veces se enreda él solo, y llega a ser confuso, muy buena nota como persona, si usted ya sabe de la materia que se ve en el curso le va a ir muy bien, si para usted es materia nueva busque un profe que explique mejor'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '8222cbd5cea57a5d5a7358aa40e14d72724ad2c10d3464ddbce3c0ffa44b1b9c'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'El profe es buena persona, pero cuesta mucho entenderle. Otra cosa que me disgustó mucho fue que para él toda la materia es de "kinder" por lo que explica muy rápido y si usted se devuelve a preguntarle en ocasiones (indirectamente) te hace sentir tonto por preguntar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '295b800d65d7976e413ed6e61b3693015a37aa09de82d69be5093d290a7eb23e'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Deja trabajos innecesariamente largos que no ayudan para practicar, es muy desordenado explicando y siempre se pasa diciendo que la materia es complicada'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-06-15T00:00:00+00:00'::TIMESTAMPTZ, '0a333a794aeb0284baa387aafeab51d5f8e7bd7d9154a8d7c5c27f09ab4b623a'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Todo el tiempo se salta partes grandes de un ejercicio por que "ustedes ya saben hacer eso" o "es muy obvio" y lo deja a uno super perdido en los ejercicios, todo el tiempo dice que la materia es super difícil y le quita a uno la motivación, si le fue masomenos en Calculo diferencial no lleve con él'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-27T00:00:00+00:00'::TIMESTAMPTZ, 'd0fb30a29230b3087fa9c87cd40b972543c2e4da9e838112a76a7fea684d8a8c'::TEXT, ARRAY[634]::BIGINT[]),
    (506::BIGINT, 'No es mal profe, aunque si va muy rapido, y lee las presentaciones. A veces mas bien lo confunde a uno. Sin embargo, si usted va a consulta el le ayuda mucho. Lo recomiendo si ya llevo la clase, o si ya sabe algo de la materia.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-02-19T00:00:00+00:00'::TIMESTAMPTZ, '8cf2d53c257dda6d7aeae1288257811ea656ae6d3f529be1dc8f27bb532d38ca'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'solo se sienta a resolver ejercicios en el proyector desde la compu y asume que todos van bien. no pregunta y cuesta que le tome la palabra'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-21T00:00:00+00:00'::TIMESTAMPTZ, '490bf0b11ad759bbdb3e4020b934dedae6be33c00f46712b3d9191357042df14'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'El profe intenta ayudar pero no lo logra, en presencial dijo que nadie iba a pasar con él desde el primer día, en virtual intentaba mejorar sin embargo asumía que uno ya sabia todo y solo llegaba a resolver unos cuatro ejercicios, nunca dejaba practica.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-30T00:00:00+00:00'::TIMESTAMPTZ, '3f26f46b7dbdf439ac139bbc505eed553301c677cadd42fa9153dfeebbaeb486'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Es un excelente profesor ya que explica muy bien la materia y se preocupa por el aprendizaje del estudiante. En modalidad virtual es excelente y trata de que todo sea lo suficientemente claro. Los ejemplos que utiliza son lo más cercano al examen y eso ayuda también.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'be70b318ab368ff6e2f9a0b26a5bd7e378070ad090b6f8c6bfaec29c9abdfd9b'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '08488f55bc16c3122e379ffda73956cfdaaceb39a4ed5082b7d8d8b4d22d632b'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'fd2ffb41bdf0ffa6d6b31ce054ca3961a0ad5eb120f861f306e6543e0d74636f'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'dd0c21d44e3ca9f329a8cd3a18a1a9030a0f2eb34ed54bde30701c2bfdeeb3ba'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '30028f9691705e1cb5dd81688892a60d00adf91ab9fb1a49709486ab63502bd9'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'El mejor, se nota que hubo un cambio positivo para el profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '527e925953560f2c20ecf2daaafb5ec39de780fc07d276378c6d4ed82c6f4968'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Explica muy bien y ayuda en todo lo que necesitan'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'da392db992b8ad378b349a38ff256460188b2fc3aa3a21f7a94132cd7935d2f0'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Es un excelente profe que ayuda si usted le pregunta y trata de que todo quede muy claro en la clase, hace bastantes ejemplos que pueden ser medio complicados pero por lo menos no enseña algo sencillo en clase para que se lo suenen en el examen. Virtual es muy bueno llevarlo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'ce51afca4674c27d795fe72599aece4c14ed7294c10013b3a26229351a1ba53e'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'No entiendo porque tiene tan baja calificación, es un buen profe, hace ver la materia super sencilla, si uno tiene dudas busca la manera de que usted entienda. (Modalidad virtual y el primer mes en clases presenciales)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'd38cedac400a1dbb47db62c20439edd8b6fcc13aa1c814fefb3e02bbe5c4c433'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'MUY BUEN PROFESOR, EXPLICA MUY BIEN LOS TEMAS'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '0e8965e720930fd3dbb51f97145f87e8e596b69f1fa6e9ee1b0856d1bf88e5a2'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Es buen profe, siento que es mejor en modalidad virtual y se le nota mucho el compromiso. El programa de mate discreta virtual es muy malo pero aun así él logra salvar bastante bien la clase. A veces puede confundir un poco pero si usted le pregunta lo ayuda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'f7318bc0059f1816836c568d6cc6665685b4f9ed65ef7e047b259e7e9d01cf37'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2493e8430e96065cea76eb28395893782096c3045806c05b5bc7830cb5e2396'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'El profe trata de hacer las cosas bien, pero termina confundiendo, lo peor es que justo a final de semestre le da un ataque por hacer quices en cada clase y para peores quices en pareja y a veces toca con gente que más bien lo afecta a uno... Si lleva cálculo por 2da vez ok, si no, no lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, '7683d511517dfe1ff3acf58bc4ed9c9f2e966bfc2e451a7a6dcbb7684d346069'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Él explica con los ejemplos mas fáciles. No lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'a37a049a71a36a40581cb561367bbf62e88b2c825b0249cddac59475691824f3'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Sabe bastante sobre el tema, pero da ejemplos muy raros que hacen que uno se distraiga y no termine de entender las comparaciones que intenta hacer'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '6cca1ecda759527b6731543d76b29eeb90975e01b161da2ed363e3feba363e1c'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Él lo intenta... sólo que no lo logra. Simplemente pésimo profe, no sabe explicar y se traba cuando lo intenta. Cabe destacar que el curso no es fácil, pero cuando llega un suplente un día, se nota la diferencia abismal. Esta persona no nació para enseñar, aunque es buena persona.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-08-06T00:00:00+00:00'::TIMESTAMPTZ, '7572cb04fc6be2c75866a8dd332be972238c01378176dac2e1720608bad36149'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Mate le puede costar a cualquiera pero el profesor es bastante malo, no suele cubrir dudas extra clase, no presta atención a los estudiantes y es muy negativo, desde el primer día le dice a todos los estudiantes como “motivación” nadie pasa mis cursos y ustedes no lo van a pasar, bastante mal, no lo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a55656e5807fd5101908e6bc187c13bbd1178c19d30e36e7a751ca2d64b058e2'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'En si el profe es bueno, pero no solo nos podemos quedar con lo que se vió en clase, obviamente hay que prácticar afuera.. La mayoria de quices son grupales nivel examen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e937960140a1896612ffe430fdbac0ad0955079af5260856b9a04083353193a6'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Muy Mickey Mouse el curso. Mis respetos JL'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4edf5201cb3aea43dea51f78e865f3077477d74cbf81b47613091b8eef487650'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '605a3a2268360ae1b983f88db1194635dae3fd107dca116db113e261ddf92c63'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Es un pésimo profesor, se traba cuando explica, no recomiendo que lo matriculen'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-05-16T00:00:00+00:00'::TIMESTAMPTZ, '08cf3f383e18f4788eca47615f9e5230edffa4f10476225d1426b86696cbe0c0'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Muy buen profesor. Casi no hay quices y las tareas son ejercicios de examenes. Explica bien, se enfoca más en lo necesario para resolver los ejercicios que en la teoría en general.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9b366929a9e2d3c7abb754bea8e9870ba7f53a867d95696eed6d5bc611a2edfc'::TEXT, ARRAY[634]::BIGINT[]),
    (506::BIGINT, 'De 1 al 10, lo que escribe en la pizarra es un 2, usa unos folletos de práctica pdf, eso hace que tiene que estar subiendo y bajando y no lo deja a ud copiar, no se le entiende nada. Ni se embarque. Se rescatan las tareas y quices que pone con dificultad de exámenes'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, '34a57b2cb700e112c1540d2544369efe9fae90904177848606eac61322e8013d'::TEXT, ARRAY[634]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-12T00:00:00+00:00'::TIMESTAMPTZ, '0441458685a6379893013c1893382e94cd234f9ec3eb4a457f67a934f0ec9d7d'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Excelente profe. Ayuda mucho con las dudas, explica muy claro y repite 100 veces si es necesario'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-12T00:00:00+00:00'::TIMESTAMPTZ, '9600405afba03f15b355ef863c7dc5345e243a1a4177a2c7313c0382bd3eaf5f'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Muy buen profe, se interesa mucho por los estudiantes. Si él ve que usted le pone ayuda bastante, siempre atiende cualquier consulta y las clases con él son vacilonas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '204c5bae4f06c588763e7b8eb51ba6fbafff45b1097bd8ebb2a463f9e2eb4108'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'La clase son presentaciones de PP, si ayuda bastante'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c8549ffc454d143c158e4f18920b20608eeb38a3ce33c1045ed2ac90c7cb0b4d'::TEXT, ARRAY[563, 1018, 2439]::BIGINT[]),
    (506::BIGINT, 'Super recomendado. Es un excelente profe, hace la clase bastante dinamica y se interesa en que uno aprenda. Solo se necesita hacer las tareas que deja para llevar la materia al dia y salir bien en los examenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9c870a9ade1598a95e0e282b0b3aad71fb492759e919019c815aa97c74e6cfcf'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'A veces se pierde en lo que está diciendo, se olvida de la clase y empieza a hablar de su vida, pero lo examenes los hace con lo mismo que se ve en clase o deja de tarea, si usted hace la tarea se saca bien el examen'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'a8d8f67f56b38eb5060614255cc0ea52a401341e3ad9d0dbf2b33c1449a83106'::TEXT, ARRAY[1638]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e17fb6327c4c967953b4c254306cbbb739b27b9d2c6eb77557a1ebb5ccfc1142'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'a0126393772c1eecb1acef6a43f1a86263f59c045ddae49384dd92cf4dd5357f'::TEXT, ARRAY[4476]::BIGINT[]),
    (506::BIGINT, 'Explica muy bien la materia, siempre trata de que entendás bien, hace ejercicios rudos en clase para que tengan un buen nivel de mate. Le interesa mucho que sus estudiantes vayan a consulta, pregunten, pasen a la pizarra, y es muy abierto a recibir críticas, en fin, recomendadísimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'c19c73e12ff3f281ea7d4c079d3310f074089f891f31d58868bc4f2501609007'::TEXT, ARRAY[2439]::BIGINT[]),
    (506::BIGINT, 'Prepara bien al estudiante al punto que los parciales no son nada del otro mundo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '13c75d4c69d6a19d277317daff31ff04b3ba069d2794161f59477021343e7704'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'El profe califica rudillo, lo bueno es que las tareas y los quises son regalados. Es sincero y se nota que quiere que uno aprenda'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'f096234923da52efdf756929c28710cb215b6b824a8bd2f97544115fc46b8839'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Es una basura de profesor, califica sin piedad, no explica nada claro y los quices son nivel Dios.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '5736cc3dbf603f1d876df0b01897a642297b391db5f658f9863cb291bdf5acad'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'No matricular con él! Lo único rescatable es que da la MITAD del porcentaje de tareas y quiz de la clase casi regalados.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-07T00:00:00+00:00'::TIMESTAMPTZ, '460882996e03c12e8c23ac9b2313a47bb43faed09dfa819474e06fb10318d822'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'No es muy ordenado y si le dan cuerda se pierde la clase con historias, sin embargo se aprende y son muy amenas sus clases. Eso si HAY que estudiar porque si se le mete el agua hace quizes a matar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '19b116526773a57e4c192a6bc6d7032489da066958f2ed615273e6ab2708bfbb'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'hay que ponerle claro, siempre es recomendable aunque sea practicar o repasar la materia antes de ir a clase ,asi la entiende mejor, los quices no son faciles, hace practicas buenas en clase'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2016-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd06a5a7982e36835efe8295c5288179a1c1c8b1ca9fb9d8cfcfc8a0d09edf3c2'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Demasiado malo, va muy rápido y es muy desorndeado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-01T00:00:00+00:00'::TIMESTAMPTZ, '4ee1faaa16fe49fb1c04f391f1612cad54cc74e316ace3f9fb4cbac116cb3f7e'::TEXT, ARRAY[563]::BIGINT[]),
    (506::BIGINT, 'Si ya a repetido el curso lo bastante, no cuesta tanto entenderle. Sí, gasta el tiempo hablando sobre futbol e historias que nada que ver, pero bueno... no es tan imposible'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, '627da8a8f5b617cab7bc5f4071087cc6926d6e8a96f18a112b1c1be441c383bd'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Es muy desordenado para explicar y nunca se le entiende, hay que ir a consulta con otros profes si se quiere pasar el curso. Además, califica rudo.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'cee3849e50d3bc0c9b55bf6161a7c7b9ac3e79e5de8dea10f86398b198c4a5d3'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Pésimo profesor, las clases son sobre sus historias en la Universidad cuando era estudiante. El curso se pasa pero es difícil y no se aprende.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'efe628c798a630d2adb97b0edb909d7bd84327657375522d8e704864512171e0'::TEXT, ARRAY[1684]::BIGINT[]),
    (506::BIGINT, 'Nunca volveré a llevar algún curso con él. Sabe mucho pero no sabe explicar para nada. Y se hecha cada historia.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-09T00:00:00+00:00'::TIMESTAMPTZ, '25f09305aa97028564fb06e80f456c4aa60b3daa9b088410fda95590e1421672'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'No explica mucho, hace ejemplos muy raros y quices horribles. Además, los exámenes los califica rudo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, '2e07888b2900ac72940203b30cc9d33b9c63b934839ec8501c5fb601483a60a1'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-18T00:00:00+00:00'::TIMESTAMPTZ, '44c48247e0c8eda042f4280ac6139927aebfcd4c1aca812657fb72ccdcf84f03'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Cada profesor tiene su fuerte, en este caso, yo recomendaría a este profe para ecuaciones, no así para otros cursos, no porque sea malo en sí, sino porque tiene una manera un poco complicada de explicar'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '07ef0954b6d5300d4a930cd2dd8691cc7a66198284f7d859be5605d192710be8'::TEXT, ARRAY[935]::BIGINT[]),
    (506::BIGINT, 'Jamás volveré a llevar un curso con él!! Cuando uno entra al TEC uno piensa que los profesores son lo mejor que hay en CR pero con este señor me lleve una gran decepción, preferi volver a llevar el curso que quedarme con lo que él "enseñó"'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-10T00:00:00+00:00'::TIMESTAMPTZ, '79edd3fe9f250f16a220b4769fd3950162d9368f5a332ce8e91148de4bb6dfae'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Es un profe demasiado complicado. Los quices son imposibles y casi no hace practicas solo explica ejemplos que de igual manera no son nada claros.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c625a8a456cf7d0041c4b744d56185e5104d115ef192f5e5cf6f9c92d05af612'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Lo único que puedo decir de este señor es que prefiero estar un año más en el TEC antes que volver a llevar un curso con él. Si se quieren joder la vida, él es su opción PERFECTA.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '9ceaa6fc65a8ccc3ef3b93416eab2610adda691ed118e440a45a0ae0b7a31375'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Es mae está solo, llega a la clase con su celular & tablet y casi ni avansa, solo explica los ejemplos, ya resueltos un libro; nose que haría si se le quedará ese libro en la casa!Además dedica parte de la clase a hablar de parejas y fútbol, creó que solo lo hace para caer bien.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '4acad7edd3888fa9b4cc8a2c4aaa7e8dd74382b9b246c3ed8f437b5557b51b89'::TEXT, ARRAY[1018]::BIGINT[]),
    (506::BIGINT, 'Pésimo, no explica bien y se enreda, pone ejemplos duros de una y los quices los hace como si fueran exámenes y si no los pierde los entrega un mes después y hasta despu''es del exámen (que p#tas??) califica duro y pasa hablando por celular. Da clases de con proyector o presentaciones de Power point.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '37bdfc2468b98ec7986d95bfec366d2332af1fcbafe2445f572446f3dec31179'::TEXT, ARRAY[605]::BIGINT[]),
    (506::BIGINT, 'Pésimo profesor, es mejor esperarse a llevar el curso con cualquier otro profe, es imparcial. No sabe explicar nada, se enreda solo, y solo evaluaciones que no aportan nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'c717651c0776fc6eea8f2737781168581060daa453834b87cabfc3601d3050ee'::TEXT, ARRAY[978]::BIGINT[]),
    (506::BIGINT, 'si tienen la oportunidad de matricular con él, desaprovechenla; le encanta quedar a los estudiantes. Si tienen suerte les regala un 40% pero para calificar exámenes es lo peor que hay.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-30T00:00:00+00:00'::TIMESTAMPTZ, 'e9d06ec714b6a4799439042342bc886267c329b8880ec052730ab054ed722689'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
